--- a/test/query-record.test.ts
+++ b/test/query-record.test.ts
@@ -10,4 +10,33 @@ describe('query records', () => {
   it('canonicalizes key order', () => {
     expect(canonicalize('name=Ada&city=Boston')).toBe('city=Boston&name=Ada');
   });
+
+  it('orders Unicode keys by code point', () => {
+    const keys = ['', 'a', '&', '=', '%', 'é', '中', '\uE000', '\u{10000}', '🚀'];
+
+    const compareByCodePoint = (left: string, right: string): number => {
+      const leftPoints = Array.from(left, (character) => character.codePointAt(0)!);
+      const rightPoints = Array.from(right, (character) => character.codePointAt(0)!);
+
+      for (let index = 0; index < Math.min(leftPoints.length, rightPoints.length); index++) {
+        const difference = leftPoints[index] - rightPoints[index];
+        if (difference !== 0) return difference;
+      }
+
+      return leftPoints.length - rightPoints.length;
+    };
+
+    for (let left = 0; left < keys.length; left++) {
+      for (let right = left + 1; right < keys.length; right++) {
+        const pair = [keys[left], keys[right]];
+        const record = Object.fromEntries(pair.map((key) => [key, 'value']));
+        const firstSegment = encodeRecord(record).split('&')[0];
+        const encodedKey = firstSegment.slice(0, firstSegment.indexOf('='));
+        const firstEncodedKey = decodeURIComponent(encodedKey);
+        const expectedFirstKey = [...pair].sort(compareByCodePoint)[0];
+
+        expect(firstEncodedKey).toBe(expectedFirstKey);
+      }
+    }
+  });
 });
```

